// date_trunc rolls days up to the bucket. `unit` is caller-validated (day/week/month).
func (q *Queries) ListCompanyActivity(ctx context.Context, arg ListCompanyActivityParams) ([]ListCompanyActivityRow, error) {
	rows, err := q.db.Query(ctx, listCompanyActivity,
		arg.Unit,
		arg.FromTs,
		arg.ToTs,
		arg.CompanySlug,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCompanyActivityRow{}
	for rows.Next() {
		var i ListCompanyActivityRow
		if err := rows.Scan(&i.Period, &i.Added, &i.Removed); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listInsightsCompanies = `-- name: ListInsightsCompanies :many
SELECT
    g.company_slug,
    coalesce(c.name, g.company_slug) AS company_name,
    g.open_count,
    g.open_count_prev,
    (g.open_count - g.open_count_prev)::int AS growth,
    g.hiring_started_at
FROM insights_company_growth g
LEFT JOIN companies c ON c.slug = g.company_slug
WHERE g.open_count >= $1::int
  AND ($2::text <> 'new' OR g.hiring_started_at IS NOT NULL)
ORDER BY
    (CASE WHEN $2::text = 'new' THEN g.hiring_started_at END) DESC NULLS LAST,
    (CASE
        WHEN $2::text = 'open'     THEN g.open_count
        WHEN $2::text = '-growth'  THEN -(g.open_count - g.open_count_prev)
        ELSE (g.open_count - g.open_count_prev)
    END) DESC,
    g.open_count DESC
LIMIT $3::int
`

type ListInsightsCompaniesParams struct {
	MinOpen int32  `json:"min_open"`
	Sort    string `json:"sort"`
	Lim     int32  `json:"lim"`
}

type ListInsightsCompaniesRow struct {
	CompanySlug     string             `json:"company_slug"`
	CompanyName     string             `json:"company_name"`
	OpenCount       int32              `json:"open_count"`
	OpenCountPrev   int32              `json:"open_count_prev"`
	Growth          int32              `json:"growth"`
	HiringStartedAt pgtype.Timestamptz `json:"hiring_started_at"`
}

// The leaderboard read: companies ranked by growth (open_count - open_count_prev),
// '-growth' (freezing) reverses it, 'open' ranks by raw size; open_count is the
// tiebreak. @min_open floors the current open-count (blunts ingest-artifact spikes).
// 'new' keeps only companies that just started hiring, most recent start first.
// company_name falls back to the slug when no companies row exists.
func (q *Queries) ListInsightsCompanies(ctx context.Context, arg ListInsightsCompaniesParams) ([]ListInsightsCompaniesRow, error) {
	rows, err := q.db.Query(ctx, listInsightsCompanies, arg.MinOpen, arg.Sort, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListInsightsCompaniesRow{}
	for rows.Next() {
		var i ListInsightsCompaniesRow
		if err := rows.Scan(
			&i.CompanySlug,
			&i.CompanyName,
			&i.OpenCount,
			&i.OpenCountPrev,
			&i.Growth,
			&i.HiringStartedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listNewHiringCompanySlugs = `-- name: ListNewHiringCompanySlugs :many
SELECT company_slug FROM insights_company_growth WHERE hiring_started_at IS NOT NULL
`

// The companies rollup-company marked as having just started hiring, which
// /jobs/search?new_hiring=true narrows to. Served by insights_company_growth_hiring_started_idx.
func (q *Queries) ListNewHiringCompanySlugs(ctx context.Context) ([]string, error) {
	rows, err := q.db.Query(ctx, listNewHiringCompanySlugs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var company_slug string
		if err := rows.Scan(&company_slug); err != nil {
			return nil, err
		}
		items = append(items, company_slug)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sharedCompanyBoards = `-- name: SharedCompanyBoards :many
SELECT (c.company_slug)::text AS company_slug
FROM (
    SELECT unnest($1::text[]) AS company_slug,
           unnest($2::text[]) AS source,
           unnest($3::text[]) AS board
) c
WHERE EXISTS (
    SELECT 1 FROM jobs o
    WHERE o.source = c.source
      AND o.external_id ~>=~ (c.board || ':')
      AND o.external_id ~<~ (c.board || ';')
      AND o.company_slug <> c.company_slug
)
`

type SharedCompanyBoardsParams struct {
	CompanySlugs []string `json:"company_slugs"`
	Sources      []string `json:"sources"`
	Boards       []string `json:"boards"`
}

// Compute on the read connection. Gate 4 of ComputeInsightsCompanyGrowth's
// hiring_started_at: of the candidate companies, the ones whose board also lists another
// company. Job portals (trudvsem, arbeitsagentur, eures) carry no aggregator marker but
// list thousands of employers per board, so a portal's employer is never a fresh starter.
// The board prefix is a range on jobs_source_extid_pattern_idx: ~>=~ / ~<~ are the
// byte-order operators text_pattern_ops indexes, a runtime LIKE pattern is not, and ';'
// is the byte after ':'.
func (q *Queries) SharedCompanyBoards(ctx context.Context, arg SharedCompanyBoardsParams) ([]string, error) {
	rows, err := q.db.Query(ctx, sharedCompanyBoards, arg.CompanySlugs, arg.Sources, arg.Boards)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var company_slug string
		if err := rows.Scan(&company_slug); err != nil {
			return nil, err
		}
		items = append(items, company_slug)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
